select count(*) from integrated_mutation_file

		platform=#{platform}
		 and specimen_type=#{specimen_type}
		 and subbarcode=#{subbarcode}
		 and product_name=#{product_name}
		and clinicalremark=#{clinicalremark}
		 and gene=#{gene}
		 and mutation like '%' #{mutation} '%'
		 and hospital=#{hospital}
		 and fastcode=#{fastcode}

			and subbarcode in

				#{item}


		and analysis_date between #{tested_date_B} and #{tested_date_N}


select platform,specimen_type,subbarcode,product_name,clinicalremark,gene,analysis_date,mutation,mutation_frequency,hospital
	from integrated_mutation_file

		platform=#{platform}
		 and specimen_type=#{specimen_type}
		 and subbarcode=#{subbarcode}
		 and product_name=#{product_name}
		and clinicalremark=#{clinicalremark}
		 and gene=#{gene}
		 and mutation like '%' #{mutation} '%'
		 and hospital=#{hospital}
		 and fastcode=#{fastcode}

			and subbarcode in

				#{item}


		 and analysis_date between #{tested_date_B} and #{tested_date_N}

	limit #{pageNo},#{pageSize}

select distinct received_date, subbarcode 
	from integrated_mutation_file

		platform=#{platform}
		 and specimen_type=#{specimen_type}
		 and subbarcode=#{subbarcode}
		 and product_name=#{product_name}
		and clinicalremark=#{clinicalremark}
		 and gene=#{gene}
		 and mutation like '%' #{mutation} '%'
		 and hospital=#{hospital}
		 and fastcode=#{fastcode}
		 and analysis_date between #{tested_date_B} and #{tested_date_N}
